def find_largest_palindromic_cube(N: int) -> int:
    largest_palindromic_cube = 0
    number = 1
    while True:
        cube = number ** 3
        if cube > N:
            break
        cube_str = str(cube)
        if cube_str == cube_str[::-1]:
            largest_palindromic_cube = cube
        number += 1
    return largest_palindromic_cube
